doubly_linked_list.node_structure:
struct DNode {
    int data;
    struct DNode *prev;
    struct DNode *next;
};

doubly_linked_list.c_program:
#include <stdio.h>
#include <stdlib.h>

struct DNode {
    int data;
    struct DNode *prev;
    struct DNode *next;
};

struct DNode* createDNode(int val) {
    struct DNode *n = (struct DNode *)malloc(sizeof(struct DNode));
    n->data = val;
    n->prev = NULL;
    n->next = NULL;
    return n;
}

struct DNode* insertFront(struct DNode *head, int val) {
    struct DNode *n = createDNode(val);
    if (head) {
        n->next = head;
        head->prev = n;
    }
    return n;
}

struct DNode* insertEnd(struct DNode *head, int val) {
    struct DNode *n = createDNode(val);
    if (!head) return n;
    struct DNode *t = head;
    while (t->next) t = t->next;
    t->next = n;
    n->prev = t;
    return head;
}

void displayForward(struct DNode *head) {
    printf("Forward: NULL <-> ");
    while (head) {
        printf("[%d] <-> ", head->data);
        head = head->next;
    }
    printf("NULL\n");
}

int main(void) {
    struct DNode *head = NULL;
    head = insertEnd(head, 10);
    head = insertEnd(head, 20);
    head = insertFront(head, 5);
    displayForward(head);
    return 0;
}

