struct CNode {
    int data;
    struct CNode *next;
};

circular_linked_list.c_program:
#include <stdio.h>
#include <stdlib.h>

struct CNode {
    int data;
    struct CNode *next;
};

struct CNode* insertInCLL(struct CNode *last, int val) {
    struct CNode *n = (struct CNode *)malloc(sizeof(struct CNode));
    n->data = val;
    if (!last) {
        n->next = n;
        return n;
    }
    n->next = last->next;
    last->next = n;
    return n;
}

void displayCLL(struct CNode *last) {
    if (!last) return;
    struct CNode *head = last->next;
    struct CNode *curr = head;
    printf("Circular: ");
    do {
        printf("[%d] -> ", curr->data);
        curr = curr->next;
    } while (curr != head);
    printf("(head: %d)\n", head->data);
}

int main(void) {
    struct CNode *last = NULL;
    last = insertInCLL(last, 10);
    last = insertInCLL(last, 20);
    last = insertInCLL(last, 30);
    displayCLL(last);
    return 0;
}
